function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = [3, 10, 10000][int(0, 2)];
    // Mixed signs, only non-negative values, or only negative values.
    const [low, high] = [[-top, top], [-top, top], [0, top], [-top, -1]][int(0, 3)];
    return [Array.from({ length: int(1, 8) }, () => int(low, high))];
  }
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: 2000 }, () => int(-10000, 10000))];
  if (shape === 1) return [Array.from({ length: 2000 }, () => int(-10000, -1))];
  // Mostly small positive values with rare large negative ones that are worth deleting.
  return [Array.from({ length: 2000 }, () => rand() < 0.05 ? int(-10000, -5000) : int(-20, 30))];
}
